htmlTemplate.css:
:root {
  --navy: #002f6d;
  --band-gray-bg: #d1d5db;
  --band-gray-text: #111827;
  --body-text: #111827;
  --muted: #9CA3AF;
  --alt-row: #F4F6FA;
  --photo-bg: #F3F4F6;
}

* { box-sizing: border-box; }

body {
  font-family: Helvetica, Arial, sans-serif;
  font-size: 10pt;
  color: var(--body-text);
}

.cover-frame, .sheet-outer-frame { border: 0.75pt solid var(--navy); }
.page-break { page-break-after: always; }

/* ── Metadata block: logo | project info | report name + date table ── */
.meta-block {
  display: flex; flex-direction: row;
  border: 1pt solid var(--navy); margin-bottom: 2pt;
}
.meta-logo-col {
  flex: 0.7; padding: 3pt 6pt; border-right: 1pt solid var(--navy);
  display: flex; align-items: center; justify-content: center;
}
.logo-placeholder {
  width: 95pt; height: 36pt; border: 0.75pt dashed var(--muted); background: #ffffff;
}
.meta-info-col { flex: 1.1; padding: 3pt 8pt; border-right: 1pt solid var(--navy); }
.meta-project-name {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 11pt; color: var(--navy); margin-bottom: 2pt;
}
.meta-line { display: flex; flex-direction: row; margin-top: 0.5pt; }
.meta-line-label {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 9pt; color: var(--body-text); width: 68pt;
}
.meta-line-value { font-size: 9pt; color: var(--body-text); flex: 1; }
.meta-right { flex: 1.2; display: flex; flex-direction: column; }
.meta-report-name {
  display: flex; flex-direction: row; padding: 6pt 8pt; border-bottom: 1pt solid var(--navy);
}
.meta-report-name-label {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10pt; width: 90pt;
}
.meta-report-name-value {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10pt; color: var(--navy); flex: 1;
}
.meta-date-table { width: 100%; border-collapse: collapse; flex-grow: 1; }
.meta-date-table th {
  background: var(--navy); color: #ffffff;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 8.5pt; text-align: center; padding: 3pt 4pt; border-right: 0.5pt solid #ffffff;
}
.meta-date-table td {
  text-align: center; font-size: 10pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 4pt; border-right: 1pt solid var(--navy);
}
.meta-date-table td .weekday { font-size: 9pt; font-weight: normal; display: block; }

/* ── Title / section bands ── */
.title-band {
  background: var(--navy); color: #ffffff; padding: 4pt 0; text-align: center;
  margin: 2pt 0 3pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif;
  font-weight: bold; font-size: 13pt; letter-spacing: 0.3pt;
}
.section-band {
  background: var(--band-gray-bg); color: var(--band-gray-text); padding: 2.5pt 8pt;
  margin-top: 3pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif;
  font-weight: bold; font-size: 10.5pt; letter-spacing: 0.2pt; text-align: left;
}
.section-band.centered { text-align: center; }
.production-table-band {
  background: var(--navy); color: #ffffff; padding: 2.5pt 8pt; margin-top: 3pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10.5pt; letter-spacing: 0.2pt; text-align: center;
}

/* ── Narrative body ── */
.narrative-body { font-size: 10pt; color: var(--body-text); line-height: 1.32; padding: 2.5pt 6pt; white-space: pre-wrap; }
.narrative-empty { font-size: 10pt; color: var(--muted); font-style: italic; padding: 2.5pt 6pt; }

/* ── Photos ── */
.photos-row { display: flex; flex-direction: row; justify-content: space-between; margin-top: 4pt; gap: 10pt; }
.photo-cell { width: 100%; }
.photo-frame {
  width: 100%; height: 140pt; border: 0.75pt solid var(--navy); background: var(--photo-bg);
  display: flex; align-items: center; justify-content: center;
}
.photo-placeholder { font-size: 10pt; color: var(--muted); }
.photo-label {
  font-size: 10pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  color: var(--body-text); margin-top: 3pt; text-align: center;
}

/* ── Generic tables ── */
.metrics-table, .std-table { width: 100%; border-collapse: collapse; border: 0.5pt solid var(--navy); margin-top: 0; }
.metrics-footnote { font-size: 7.5pt; font-style: italic; color: var(--muted); margin-top: 3pt; text-align: right; }
.metrics-table th, .std-table th {
  background: var(--band-gray-bg); color: var(--band-gray-text);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 9.5pt; padding: 3.5pt 6pt; text-align: center; letter-spacing: 0.3pt;
  border: 0.5pt solid var(--navy);
}
.metrics-table th.label-col, .std-table th.label-col { text-align: left; padding-left: 8pt; }
.metrics-table td, .std-table td {
  font-size: 9.5pt; color: var(--body-text); padding: 3pt 6pt; text-align: right;
  border: 0.5pt solid var(--navy);
}
.metrics-table td.label-col, .std-table td.label-col { text-align: left; padding-left: 8pt; }
.std-table td.center { text-align: center; }
.metrics-table tr:nth-child(even) td, .std-table tbody tr:nth-child(even) td { background: var(--alt-row); }
.metrics-empty, .table-empty { text-align: center; color: var(--muted); font-style: italic; padding: 8pt; }

/* ── Daily Activity table ─────────────────────────────────────── */
.act-table { table-layout: fixed; }
.act-table th, .act-table td { font-size: 8pt; padding: 1.5pt 4pt; }
.act-table th.act-l, .act-table td.act-l { text-align: left; }
.act-table th.act-c, .act-table td.act-c { text-align: center; }
.act-table th.act-r, .act-table td.act-r { text-align: right; }
.act-table td.act-pad { color: var(--muted); }

/* ── Equipment list ── */
.equipment-list { font-size: 10pt; padding: 4pt 8pt; }
.equipment-list li { margin-bottom: 2pt; }

/* ── Footer ── */
.footer { font-size: 7pt; color: var(--muted); text-align: center; margin-top: 10pt; }

/* ── Sheet header (Production Sheet / Dredge Progress / Safety) ── */
.sheet-meta-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); }
.sheet-logo-col {
  flex: 0 0 130pt; padding: 4pt 6pt; border-right: 0.75pt solid var(--navy);
  display: flex; align-items: center; justify-content: center;
}
.sheet-title-col {
  flex: 0 0 130pt; padding: 4pt 6pt; border-right: 0.75pt solid var(--navy);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 12pt; color: var(--body-text); display: flex; align-items: center;
}
.sheet-equipment-col {
  flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy);
  font-family: Helvetica-BoldOblique, Helvetica, Arial, sans-serif; font-style: italic; font-weight: bold;
  font-size: 15pt; color: var(--navy); display: flex; align-items: center; justify-content: center;
}
.sheet-date-table { flex: 0 0 260pt; border-collapse: collapse; }
.sheet-date-table th {
  background: var(--navy); color: #fff; font-size: 8pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 2pt 4pt; text-align: center; border-right: 0.5pt solid #fff;
}
.sheet-date-table td {
  font-size: 9.5pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 3pt 4pt; text-align: center; border-right: 0.5pt solid var(--navy); border-top: 0.5pt solid var(--navy);
}
.sheet-date-table td .weekday { font-size: 8.5pt; font-weight: normal; display: block; }

.sheet-info-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); font-size: 9pt; }
.sheet-info-col { flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy); }
.sheet-info-col:last-child { border-right: none; }
.sheet-info-col .lbl { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; width: 70pt; display: inline-block; }

.op-time-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); }
.op-time-stat {
  flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy); text-align: center;
}
.op-time-stat:last-child { border-right: none; }
.op-time-stat .stat-label { font-size: 8pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }
.op-time-stat .stat-value { font-size: 14pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; color: var(--navy); }
.op-time-stat .stat-sub { font-size: 7.5pt; color: var(--muted); font-style: italic; }

.sheet-band {
  background: var(--navy); color: #fff; padding: 3pt 8pt; text-align: center;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt;
}
.sheet-section { padding: 6pt 8pt; }

.stats-grid { display: flex; flex-direction: row; gap: 8pt; padding: 6pt 8pt; }
.stats-grid > div { flex: 1; }
.stats-grid .box-title {
  background: var(--band-gray-bg); color: var(--band-gray-text); text-align: center;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 9pt;
  padding: 3pt; border: 0.5pt solid var(--navy); border-bottom: none;
}
.stats-grid .box-body { border: 0.5pt solid var(--navy); padding: 6pt; font-size: 9pt; min-height: 50pt; color: var(--muted); font-style: italic; text-align: center; }
.stats-grid .box-body.has-data { color: var(--body-text); font-style: normal; text-align: left; }
.flow-row { display: flex; flex-direction: row; justify-content: space-between; padding: 1.5pt 0; font-size: 8.5pt; }
.flow-row .lbl { color: var(--muted); }
.flow-row.total { border-top: 0.5pt solid var(--navy); margin-top: 3pt; padding-top: 3pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }

.delay-summary-table { width: 100%; border-collapse: collapse; font-size: 8pt; }
.delay-summary-table th {
  background: var(--band-gray-bg); color: var(--band-gray-text);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 2pt 4pt; border: 0.5pt solid var(--navy); text-align: center;
}
.delay-summary-table th.label-col { text-align: left; padding-left: 4pt; }
.delay-summary-table td { padding: 2pt 4pt; border: 0.5pt solid var(--navy); text-align: center; color: var(--body-text); }
.delay-summary-table td.label-col { text-align: left; }
.delay-summary-table tbody tr:nth-child(even) td { background: var(--alt-row); }

/* ── Dredge Progress chart skeleton ── */
.chart-legend-row { display: flex; flex-direction: row; align-items: center; padding: 6pt 8pt; gap: 16pt; font-size: 9pt; }
.chart-legend-item { display: flex; flex-direction: row; align-items: center; gap: 4pt; }
.chart-swatch { width: 12pt; height: 8pt; display: inline-block; border: 0.5pt solid var(--navy); }
.chart-placeholder {
  border: 0.75pt solid var(--navy); background: var(--photo-bg); height: 480pt;
  display: flex; align-items: center; justify-content: center; color: var(--muted);
  font-size: 11pt; font-style: italic; margin: 4pt 8pt;
}

/* ── Safety page ── */
.safety-updates-row { display: flex; flex-direction: row; border-bottom: 0.5pt solid var(--navy); font-size: 9pt; }
.safety-updates-label {
  flex: 0 0 200pt; padding: 4pt 8pt; border-right: 0.5pt solid var(--navy);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; background: var(--alt-row);
}
.safety-updates-value { flex: 1; padding: 4pt 8pt; color: var(--muted); }
.safety-two-col { display: flex; flex-direction: row; }
.safety-col { flex: 1; border-right: 0.75pt solid var(--navy); }
.safety-col:last-child { border-right: none; }
.safety-sig-row { display: flex; flex-direction: row; margin-top: 30pt; padding: 0 8pt 8pt; gap: 20pt; }
.safety-sig { flex: 1; text-align: center; font-size: 8.5pt; border-top: 0.5pt solid var(--body-text); padding-top: 3pt; }
.safety-sig-img { height: 36pt; display: block; margin: 0 auto 3pt; object-fit: contain; }
.climate-header { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 8pt; color: var(--body-text); margin-top: 3pt; }
.climate-row { display: flex; flex-direction: row; justify-content: space-between; padding-left: 8pt; font-size: 8pt; }
.climate-row .lbl { color: var(--muted); }
.climate-conditions { display: flex; flex-direction: row; justify-content: space-between; margin-top: 2pt; font-size: 8pt; }

/* ── Logo / photo image fit (added for asset embedding) ── */
.logo-img { max-width: 100%; max-height: 100%; object-fit: contain; }
.photo-img { width: 100%; height: 100%; object-fit: cover; }
.dredge-chart-img { width: 100%; height: 100%; object-fit: contain; }
.metrics-total-row td { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; border-top: 0.75pt solid var(--navy); }

.sheet-band-split { display: flex; flex-direction: row; }
.sheet-band-split .sheet-band-cell {
  background: var(--navy); color: #fff; padding: 3pt 8pt; text-align: center;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt;
  border-right: 0.5pt solid #ffffff;
}
.sheet-band-split .sheet-band-cell:first-child { flex: 0 0 230pt; }
.sheet-band-split .sheet-band-cell:last-child { flex: 1; border-right: none; }


/* ── cover-density tiers ─────────────────────────────────────────────
   Generated from the cover's own base rules, scaled per tier. The tier is
   chosen by pickDensity() in src/pages/FieldOps/lib/coverDensity.js and
   arrives as parameters.coverDensity, so the cover shrinks to fit one page
   instead of silently spilling onto a second. Scoped to .cover-frame so the
   production sheets, which share .section-band/.metrics-table, are untouched.
   `normal` is the unscaled baseline and needs no block. */

.cover-frame.cover-compact .meta-logo-col { padding: 2.64pt 5.28pt; }
.cover-frame.cover-compact .meta-info-col { padding: 2.64pt 7.04pt; }
.cover-frame.cover-compact .meta-project-name { font-size: 9.68pt; }
.cover-frame.cover-compact .meta-line-label { font-size: 7.92pt; }
.cover-frame.cover-compact .meta-line-value { font-size: 7.92pt; }
.cover-frame.cover-compact .meta-report-name { padding: 5.28pt 7.04pt; }
.cover-frame.cover-compact .meta-report-name-label { font-size: 8.8pt; }
.cover-frame.cover-compact .meta-report-name-value { font-size: 8.8pt; }
.cover-frame.cover-compact .meta-date-table th { font-size: 7.48pt; padding: 2.64pt 3.52pt; }
.cover-frame.cover-compact .meta-date-table td { font-size: 8.8pt; padding: 3.52pt; }
.cover-frame.cover-compact .meta-date-table td .weekday { font-size: 7.92pt; }
.cover-frame.cover-compact .title-band { font-size: 11.44pt; padding: 3.52pt 0; }
.cover-frame.cover-compact .section-band { font-size: 9.24pt; padding: 2.2pt 7.04pt; }
.cover-frame.cover-compact .production-table-band { font-size: 9.24pt; padding: 2.2pt 7.04pt; }
.cover-frame.cover-compact .narrative-body { font-size: 8.8pt; padding: 2.2pt 5.28pt; }
.cover-frame.cover-compact .narrative-empty { font-size: 8.8pt; padding: 2.2pt 5.28pt; }
.cover-frame.cover-compact .photo-placeholder { font-size: 8.8pt; }
.cover-frame.cover-compact .photo-label { font-size: 8.8pt; }
.cover-frame.cover-compact .metrics-footnote { font-size: 6.6pt; }
.cover-frame.cover-compact .metrics-table th { font-size: 8.36pt; padding: 3.08pt 5.28pt; }
.cover-frame.cover-compact .metrics-table td { font-size: 8.36pt; padding: 2.64pt 5.28pt; }
.cover-frame.cover-compact .photo-frame { height: 123.2pt; }

.cover-frame.cover-dense .meta-logo-col { padding: 2.34pt 4.68pt; }
.cover-frame.cover-dense .meta-info-col { padding: 2.34pt 6.24pt; }
.cover-frame.cover-dense .meta-project-name { font-size: 8.58pt; }
.cover-frame.cover-dense .meta-line-label { font-size: 7.02pt; }
.cover-frame.cover-dense .meta-line-value { font-size: 7.02pt; }
.cover-frame.cover-dense .meta-report-name { padding: 4.68pt 6.24pt; }
.cover-frame.cover-dense .meta-report-name-label { font-size: 7.8pt; }
.cover-frame.cover-dense .meta-report-name-value { font-size: 7.8pt; }
.cover-frame.cover-dense .meta-date-table th { font-size: 6.63pt; padding: 2.34pt 3.12pt; }
.cover-frame.cover-dense .meta-date-table td { font-size: 7.8pt; padding: 3.12pt; }
.cover-frame.cover-dense .meta-date-table td .weekday { font-size: 7.02pt; }
.cover-frame.cover-dense .title-band { font-size: 10.14pt; padding: 3.12pt 0; }
.cover-frame.cover-dense .section-band { font-size: 8.19pt; padding: 1.95pt 6.24pt; }
.cover-frame.cover-dense .production-table-band { font-size: 8.19pt; padding: 1.95pt 6.24pt; }
.cover-frame.cover-dense .narrative-body { font-size: 7.8pt; padding: 1.95pt 4.68pt; }
.cover-frame.cover-dense .narrative-empty { font-size: 7.8pt; padding: 1.95pt 4.68pt; }
.cover-frame.cover-dense .photo-placeholder { font-size: 7.8pt; }
.cover-frame.cover-dense .photo-label { font-size: 7.8pt; }
.cover-frame.cover-dense .metrics-footnote { font-size: 5.85pt; }
.cover-frame.cover-dense .metrics-table th { font-size: 7.41pt; padding: 2.73pt 4.68pt; }
.cover-frame.cover-dense .metrics-table td { font-size: 7.41pt; padding: 2.34pt 4.68pt; }
.cover-frame.cover-dense .photo-frame { height: 120.4pt; }

.cover-frame.cover-ultra .meta-logo-col { padding: 2.04pt 4.08pt; }
.cover-frame.cover-ultra .meta-info-col { padding: 2.04pt 5.44pt; }
.cover-frame.cover-ultra .meta-project-name { font-size: 7.48pt; }
.cover-frame.cover-ultra .meta-line-label { font-size: 6.12pt; }
.cover-frame.cover-ultra .meta-line-value { font-size: 6.12pt; }
.cover-frame.cover-ultra .meta-report-name { padding: 4.08pt 5.44pt; }
.cover-frame.cover-ultra .meta-report-name-label { font-size: 6.8pt; }
.cover-frame.cover-ultra .meta-report-name-value { font-size: 6.8pt; }
.cover-frame.cover-ultra .meta-date-table th { font-size: 5.78pt; padding: 2.04pt 2.72pt; }
.cover-frame.cover-ultra .meta-date-table td { font-size: 6.8pt; padding: 2.72pt; }
.cover-frame.cover-ultra .meta-date-table td .weekday { font-size: 6.12pt; }
.cover-frame.cover-ultra .title-band { font-size: 8.84pt; padding: 2.72pt 0; }
.cover-frame.cover-ultra .section-band { font-size: 7.14pt; padding: 1.7pt 5.44pt; }
.cover-frame.cover-ultra .production-table-band { font-size: 7.14pt; padding: 1.7pt 5.44pt; }
.cover-frame.cover-ultra .narrative-body { font-size: 6.8pt; padding: 1.7pt 4.08pt; }
.cover-frame.cover-ultra .narrative-empty { font-size: 6.8pt; padding: 1.7pt 4.08pt; }
.cover-frame.cover-ultra .photo-placeholder { font-size: 6.8pt; }
.cover-frame.cover-ultra .photo-label { font-size: 6.8pt; }
.cover-frame.cover-ultra .metrics-footnote { font-size: 5.1pt; }
.cover-frame.cover-ultra .metrics-table th { font-size: 6.46pt; padding: 2.38pt 4.08pt; }
.cover-frame.cover-ultra .metrics-table td { font-size: 6.46pt; padding: 2.04pt 4.08pt; }
.cover-frame.cover-ultra .photo-frame { height: 120.4pt; }

/* ── Daily Water / Air Monitoring pages ─────────────────────────────────── */
.mon-main { display: flex; flex-direction: row; margin-top: 4pt; gap: 8pt; }
.mon-table-col { flex: 1 1 auto; }
.mon-info-col { flex: 0 0 210pt; }
.mon-table { width: 100%; border-collapse: collapse; }
.mon-table th {
  background: var(--navy); color: #ffffff; font-size: 6.5pt; font-weight: bold;
  padding: 2.5pt 3pt; text-align: right; border: 0.5pt solid var(--navy);
}
.mon-table th:first-child { text-align: left; }
.mon-table td {
  font-size: 7pt; padding: 1.8pt 3pt; text-align: right;
  border: 0.5pt solid var(--navy); font-variant-numeric: tabular-nums;
}
.mon-table td.mon-time { text-align: left; }
.mon-table tbody tr:nth-child(even) td { background: var(--alt-row); }
.mon-block { border: 0.5pt solid var(--navy); padding: 5pt; margin-bottom: 6pt; }
.mon-block-title { font-size: 7.5pt; font-weight: bold; margin-bottom: 2pt; }
.mon-body { font-size: 7pt; line-height: 1.35; }
.mon-body-sp { margin-top: 3pt; }
.mon-kv { display: flex; flex-direction: row; justify-content: space-between; font-size: 7pt; }
.mon-kv-val { font-weight: bold; font-variant-numeric: tabular-nums; }
.mon-big { font-size: 11pt; font-weight: bold; text-align: center; }
.mon-foot { font-size: 6pt; color: #555555; margin-top: 2pt; }
.mon-warn { font-size: 6pt; color: #b45309; margin-top: 2pt; }
.mon-aerial img { width: 100%; border: 0.5pt solid var(--navy); }
.mon-chart { margin-top: 6pt; }
.mon-chart img { width: 100%; border: 0.5pt solid var(--navy); }
.mon-air-text-col { flex: 0 0 48%; }
.mon-air-aerial-col { flex: 1 1 auto; padding-left: 8pt; }
.mon-air-aerial-col img { width: 100%; border: 0.5pt solid var(--navy); }
.mon-air-charts { display: flex; flex-direction: row; margin-top: 6pt; gap: 6pt; }
.mon-air-chart { flex: 1 1 50%; }
.mon-air-chart img { width: 100%; border: 0.5pt solid var(--navy); }

/* ── Safety: equipment grouped by category, and by company for subs ─────── */
.equip-group { margin-bottom: 5pt; }
.equip-group:last-child { margin-bottom: 0; }
.equip-group-title {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 9pt; color: var(--navy); padding: 0 8pt 1pt;
}
.equip-group .equipment-list { padding-top: 0; padding-bottom: 0; }
.equip-inline { font-size: 7pt; line-height: 1.15; padding: 0 8pt; }
/* One-page invariant: a crowded roster (subs present AND >55 items) drops a
   density tier so the signatures stay on page one. */
.equip-tight .equip-group { margin-bottom: 2pt; }
.equip-tight .equip-group-title { font-size: 7.5pt; padding-bottom: 0; }
.equip-tight .equipment-list { font-size: 7pt; }
.equip-tight .equipment-list li { margin-bottom: 0; }
.equip-tight .equip-inline { font-size: 6pt; line-height: 1.05; }
